package in.jharkhand.civic.controller;
import in.jharkhand.civic.repository.JsonStore;import in.jharkhand.civic.service.ReferenceService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class DepartmentInstitutionController{private final JsonStore s;private final ReferenceService ref;public DepartmentInstitutionController(JsonStore s,ReferenceService r){this.s=s;this.ref=r;}@GetMapping("/departments/{id}/problems")List<Map<String,Object>> dp(@PathVariable String id){return s.read("problems.json").stream().filter(x->id.equals(String.valueOf(x.get("assignedDepartmentId")))).toList();}@GetMapping("/institutions/{id}/problems")List<Map<String,Object>> ip(@PathVariable String id){return s.read("problems.json").stream().filter(x->id.equals(String.valueOf(x.get("assignedInstitutionId")))).toList();}}
